Reviewing our zapier-platform CLI app before we push 1.0.0 for Quillbase, a CRM. Here are the parts I'm unsure about:

```js
// index.js
const App = {
  version: require('./package.json').version,
  platformVersion: require('zapier-platform-core').version,
  authentication: {
    type: 'oauth2',
    oauth2Config: {
      authorizeUrl: { url: 'https://auth.quillbase.test/oauth/authorize', params: { client_id: 'qb_live_8f3a', response_type: 'code' } },
      getAccessToken: { url: 'https://auth.quillbase.test/oauth/token', method: 'POST', body: { client_id: 'qb_live_8f3a', client_secret: 'sk_live_9c1e77d2', code: '{{bundle.inputData.code}}' } },
    },
    test: { url: 'https://api.quillbase.test/v2/contacts?limit=500' },
    connectionLabel: '{{bundle.authData.access_token}}',
  },
  afterResponse: [
    (response, z, bundle) => {
      if (response.status >= 400) {
        // keep Zaps alive: never let a failure bubble up
        return { ...response, status: 200, data: { error: response.data } };
      }
      return response;
    },
  ],
  creates: {
    create_contact: {
      operation: {
        perform: async (z, bundle) => {
          const res = await z.request({ url: 'https://api.quillbase.test/v2/contacts', method: 'POST', body: bundle.inputData, skipThrowForStatus: true });
          if (res.status === 409) throw new Error('Contact already exists');
          return res.data;
        },
      },
    },
  },
  triggers: {
    new_attachment: {
      operation: {
        perform: async (z, bundle) => {
          const res = await z.request({ url: 'https://api.quillbase.test/v2/attachments?sort=-created_at' });
          return res.data.map((a) => ({ ...a, file: z.stashFile(z.request({ url: a.download_url, raw: true })) }));
        },
      },
    },
  },
};
```

package.json has `"zapier-platform-core": "^16.1.0"`. Our API returns HTTP 200 with `{ "error": "token_expired" }` when an access token expires, and HTTP 429 with a `Retry-After` header when we rate-limit. CI runs `zapier test` on Node 18. What should change before we push?
